/**
 * The column map for every D365 entity the converter accepts.
 *
 * Keys are D365 **logical** names — never the display name a user can rename in
 * the view, and never a column position. Values are the staging column and the
 * coercion applied to the cell text.
 *
 * Adding an entity means three edits in lockstep: an entry here, a `createTable`
 * in a migration, and a `LEGACY_TABLES` entry in src/seed/legacy-import.js. The
 * column map drives the `unnest` casts, so a missing or misnamed column fails
 * the whole import rather than silently nulling.
 */

export const TEXT = 'text'
export const NUM = 'num'
export const DATE = 'date'
export const DATETIME = 'datetime'
export const BOOL = 'bool'

const col = (name, kind = TEXT) => [name, kind]

/**
 * Columns pulled from a RELATED entity export arrive as
 * `<relationship-guid>.<logical>`, e.g. "5c5e1693-….atelier_code" for
 * "Code (Product) (Product Prices)". The GUID is the relationship id and would
 * change if the view were rebuilt, so those are matched on the suffix instead: a
 * key of "*.atelier_code" matches any prefix. Bare logical names always win.
 */
export const WILDCARD = '*.'

// D365 lookup/GUID columns that carry no analytical value, plus the audit-noise
// columns that are empty in every row of every export we have seen.
export const IGNORED = new Set([
  'checksumLogicalName', 'createdonbehalfby', 'modifiedonbehalfby',
  'owningbusinessunit', 'overriddencreatedon',
])

// Dropped here so they never reach the database, the normalised JSON, or a backup
// of either: supplier bank details, and the D365 portal identity columns on
// `contact` (which include adx_identity_passwordhash and the security stamp).
export const SENSITIVE_PREFIXES = ['fulmxero_bankaccount', 'adx_identity_']

